  grid-template-rows:58px minmax(calc(var(--large-round-slot) - 70px),max-content) max-content;
 }
 .scene--game .stable-round.large-blitz-text .round-top:has(.blitz-status)>.game-eyebrow{order:1}
}

.scene--game .stable-round.large-blitz-text .round-bottom{min-height:min-content}
.scene--game .stable-round.large-blitz-text .blitz-control>span{white-space:normal;overflow-wrap:anywhere}
/* Unknown historical wording may exceed today's edited conditions. Preserve
   all saved text and scroll the existing game surface, never the condition. */
.scene--game .play-inner.stable-round.long-round-text{overflow-y:auto;overflow-x:hidden}
@media(min-height:481px){
 .scene--game .play-inner.stable-round.long-round-text{grid-template-rows:var(--round-slot-size) var(--round-card-size) minmax(min-content,1fr) max-content}
}
@media(max-height:480px){
 .scene--game .play-inner.stable-round.long-round-text{grid-template-rows:58px minmax(min-content,1fr) max-content}
}

